def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return
    try:
        nums = list(map(int, data))
    except:
        print(-1)
        return

    if not nums:
        print(-1)
        return

    result = []
    for num in nums:
        result.append(str(num))

    print(' '.join(result))

if __name__ == "__main__":
    main()
